			path:                      "testdata/import_single_namespace_foo",
			expectedGetNSReqs:         1,
			expectedCreateFlagReqs:    2,
			expectedCreateSegmentReqs: 1,
		},
		{
			name:                      "multiple namespaces default and foo",
